def transform(grid):
    # Complete the repeating diagonal-stripe coloring, indexed by row+column.
    h, w = len(grid), len(grid[0])
    known = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                s = r + c
                if s in known and known[s] != value:
                    raise ValueError('inconsistent stripe')
                known[s] = value
    # Infer the smallest period consistent with all observed diagonal stripes.
    period = next(p for p in range(1, h + w) if all(
        known[a] == known[b] for a in known for b in known
        if a % p == b % p))
    residues = {}
    for s, color in known.items():
        residues[s % period] = color
    # For unobserved residues, the demonstration task uses a cyclic stripe word;
    # this input supplies observed stripes at each relevant residue.
    if len(residues) != period:
        raise ValueError('insufficient stripe seeds')
    return [[residues[(r+c) % period] for c in range(w)] for r in range(h)]
